<?php if (!defined('ABSPATH')) { exit; } get_header(); ?>
<main id="main-content" class="singular-main wrap" tabindex="-1" data-modal-inert><?php if (function_exists('shiki_breadcrumbs')) { shiki_breadcrumbs(); } ?><?php while (have_posts()) { the_post(); ?><article id="post-<?php the_ID(); ?>" <?php post_class('reading-article'); ?>><header class="article-header"><div class="article-categories"><?php the_category(' '); ?></div><h1><?php echo esc_html(get_the_title() ?: '無題の記事'); ?></h1><div class="article-meta"><span>公開 <time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date('Y.m.d')); ?></time></span><?php if (get_the_modified_time('U') > get_the_time('U')) { ?><span>更新 <time datetime="<?php echo esc_attr(get_the_modified_date('c')); ?>"><?php echo esc_html(get_the_modified_date('Y.m.d')); ?></time></span><?php } ?><button type="button" class="reading-toggle" aria-pressed="false" hidden>読書表示</button></div></header><?php if (has_post_thumbnail() && !post_password_required()) { ?><figure class="article-featured"><?php the_post_thumbnail('shiki-hero', ['loading' => 'eager', 'fetchpriority' => 'high']); ?><?php if (get_the_post_thumbnail_caption()) { ?><figcaption><?php echo esc_html(get_the_post_thumbnail_caption()); ?></figcaption><?php } ?></figure><?php } ?><div class="article-layout"><div class="entry-content"><?php the_content(); wp_link_pages(['before' => '<nav class="page-links-nav" aria-label="記事のページ分割">ページ: ', 'after' => '</nav>']); ?></div><?php if (!post_password_required()) { ?><aside class="article-sidebar" aria-label="記事の補足"><p class="eyebrow">SEASONAL NOTE</p><p class="sidebar-title">日々に、小さな<br>季節のしおりを。</p><p>めぐる季節の楽しみを、<br>ゆっくり探してみませんか。</p><a class="text-link" href="<?php echo esc_url(home_url('/')); ?>">ほかのしおりを読む <?php echo shiki_icon('arrow'); ?></a><?php if (function_exists('shiki_ad')) { shiki_ad('sidebar'); } ?></aside><?php } ?></div><?php if (has_tag() && !post_password_required()) { ?><footer class="article-tags"><?php the_tags('<span>キーワード</span>', ' '); ?></footer><?php } ?></article><?php
if (!post_password_required() && function_exists('shiki_select_posts')) { $shiki_related = shiki_select_posts('related', [get_the_ID()], 3, get_the_ID()); if ($shiki_related) { ?><section class="related-posts content-section"><?php shiki_section_title('CONTINUE YOUR READING', 'こちらのしおりも、どうぞ。'); shiki_render_cards($shiki_related); ?></section><?php } }
if (comments_open() || get_comments_number()) { comments_template(); }
} ?></main>
